('src_phone','source','اتصال هاتفي','',9,'{}'),('src_website_form','source','فورم الموقع','',10,'{}'),('src_landing_page','source','لاند بيج','',11,'{}')
insert into public.configuration(id,category,label,body,sort_order,meta)values
('reply_s1_hot','script','رد أول — جاهزة للحجز',$b$أهلًا {الاسم} 🌸 معاكِ {الموظفة} من رونق للجلدية والتجميل في حلوان. يسعدني أساعدك في {الخدمة}. تحبي أحجزلك أقرب ميعاد لتقييم مبدئي مع الدكتورة؟$b$,101,'{"states":["s1"],"temps":["hot"]}'),
('reply_s1_warm','script','رد أول — مهتمة',$b$أهلًا {الاسم} 🌸 معاكِ {الموظفة} من رونق. أكيد هساعدك في {الخدمة}. ممكن أعرف إيه اللي مضايقك بالتحديد وبقاله قد إيه؟$b$,102,'{"states":["s1"],"temps":["warm"]}'),
('reply_s1_cold','script','رد أول — ليد قديم أو متأخر',$b$أهلًا {الاسم}، معاكِ {الموظفة} من رونق. اتواصلتي معانا بخصوص {الخدمة} وحبيت أطمّن لو لسه محتاجة مساعدة. أنا تحت أمرك.$b$,103,'{"states":["s1"],"temps":["cold"]}'),
('reply_s2_hotwarm','script','سؤال السعر — جاهزة أو مهتمة',$b$طبعًا {الاسم}. التكلفة بتتحدد بعد تقييم الدكتورة لحالتك عشان تبقى خطة واضحة ومفيش مفاجآت. {سعر_معتمد} لو الإدارة حددت سعر استشارة/كشف. تحبي أحجزلك تقييم؟$b$,111,'{"states":["s2"],"temps":["hot","warm"]}'),
('reply_s2_cold','script','سؤال السعر — اهتمام مبدئي',$b$أهلًا {الاسم}. السعر بيختلف حسب الحالة، وأقدر أوضحلك الصورة الكاملة بعد معرفة احتياجك. تحبي نبدأ بسؤالين سريعين؟$b$,112,'{"states":["s2"],"temps":["cold"]}'),
('reply_s3_hot','script','تفاصيل — جاهزة للحجز',$b${الاسم}، {الخدمة} بتتم بعد كشف الدكتورة اللي بتحدد المناسب ليكِ وعدد الجلسات. أقرب مواعيد عندنا {مواعيد_متاحة}. أحجزلك أنهي؟$b$,121,'{"states":["s3"],"temps":["hot"]}'),
('reply_s3_warm','script','تفاصيل — مهتمة',$b$تمام {الاسم}. هشرحلك باختصار: {وصف_معتمد_للخدمة}. وبعدها لو حابة نحدد ميعاد تقييم من غير التزام.$b$,122,'{"states":["s3"],"temps":["warm"]}'),
('reply_s3_cold','script','تفاصيل — اهتمام مبدئي',$b${الاسم} باعتلك معلومة بسيطة عن {الخدمة}: {وصف_معتمد_للخدمة}. لو عندك أي سؤال أنا موجودة.$b$,123,'{"states":["s3"],"temps":["cold"]}'),
('reply_s4_hotwarm','script','هفكر / بعدين — جاهزة أو مهتمة',$b$أكيد خدي وقتك {الاسم} 🌸 تحبي أطمّنك على حاجة معينة تساعدك تقرري؟ ولو تحبي أراجع معاكِ يوم {يوم_مقترح}.$b$,131,'{"states":["s4"],"temps":["hot","warm"]}'),
('reply_s4_cold','script','هفكر / بعدين — اهتمام مبدئي',$b$تمام {الاسم}، هسيب لك الأمر براحتك. لو حبيتي نكمل أنا موجودة، وهبعتلك تذكير بسيط بعد يومين.$b$,132,'{"states":["s4"],"temps":["cold"]}'),
('reply_s5_24h','script','لا ترد — بعد ٢٤ ساعة',$b${الاسم} صباح الخير 🌸 حبيت أطمّن لو لسه محتاجة مساعدة في {الخدمة}.$b$,141,'{"states":["s5"],"temps":["warm"]}'),
('reply_s5_72h','script','لا ترد — بعد ٧٢ ساعة',$b${الاسم} المواعيد عندنا بتتغير كل يوم، لو حابة أحجزلك قوليلي اليوم والوقت المناسبين.$b$,142,'{"states":["s5"],"temps":["warm","cold"]}'),
('reply_s5_7d','script','لا ترد — بعد ٧ أيام (آخر تواصل)',$b${الاسم} ده آخر تواصل مني حتى لا أزعجك. لو احتجتي أي حاجة في أي وقت رقمنا موجود 🌸$b$,143,'{"states":["s5"],"temps":["cold"]}'),
('reply_s6_price','script','اعتراض السعر',$b$فاهمة {الاسم}، وعشان كده بنبدأ بتقييم يحدد الأنسب لميزانيتك من غير مبالغة. تحبي نعمل التقييم الأول؟$b$,151,'{"states":["s6"],"objections":["obj_price"]}'),
('reply_s6_fear','script','اعتراض الخوف أو الألم',$b$طبيعي تسألي، والدكتورة بتشرح الخطوات وبتختار الأنسب لبشرتك قبل أي إجراء، والفريق كله سيدات. أقدر أجاوبك على أي سؤال.$b$,152,'{"states":["s6"],"objections":["obj_fear"]}'),
('reply_s6_result','script','اعتراض النتيجة',$b$النتيجة بتختلف من شخص لشخص، ولذلك الدكتورة بتقيّم حالتك وتوضحلك المتوقع بصراحة، ومفيش وعود مبالغ فيها.$b$,153,'{"states":["s6"],"objections":["obj_result"]}'),
('reply_s6_time','script','اعتراض الوقت',$b$نقدر نظبط الميعاد على وقت يناسبك، قوليلي أنهي أيام وساعات أنسب.$b$,154,'{"states":["s6"],"objections":["obj_time"]}'),
('reply_s6_location','script','اعتراض المكان',$b$إحنا في حلوان {العنوان_المعتمد}، وأقدر أبعتلك اللوكيشن وأقرب مواصلة.$b$,155,'{"states":["s6"],"objections":["obj_location"]}'),
('reply_s6_family','script','اعتراض مشاركة الأسرة',$b$طبيعي تحبي تستشيري، وممكن نبعتلك معلومات تقدري تشاركيها. وخصوصيتك محفوظة معانا.$b$,156,'{"states":["s6"],"objections":["obj_family"]}'),
('reply_s7','script','تثبيت الموعد — جاهزة للحجز',$b$تمام {الاسم}! الموعد: {اليوم} {الساعة} مع {الطبيبة}. هبعتلك تأكيد ولوكيشن. هل الرقم ده هو الأنسب للتواصل؟$b$,161,'{"states":["s7"],"temps":["hot"]}'),
('reply_s8_reminder','script','تذكير قبل الموعد بـ ٢٤ ساعة',$b$تذكير بموعدك بكرة {الساعة} في رونق 🌸 لو احتجتي تغيير الموعد ابلغينا من دلوقتي.$b$,171,'{"states":["s8"]}'),
('reply_s9','script','لم تحضر — افتقاد بدون لوم',$b${الاسم} افتقدناكِ النهارده 🌸 اتمنى إن كل شيء بخير. تحبي نحدد ميعاد تاني مناسب ليكِ؟$b$,181,'{"states":["s9"]}'),
('reply_s10','script','إعادة تنشيط — مرة واحدة بعد ٣٠ يومًا',$b${الاسم} معاكِ {الموظفة} من رونق. لو لسه مهتمة بـ{الخدمة} نقدر نرتب تقييم مناسب ليكِ بدون التزام.$b$,191,'{"states":["s10"]}'),
('reply_s11','script','بعد الزيارة — شكر واطمئنان',$b$شكرًا لزيارتك {الاسم} 🌸 نتمنى تكوني مرتاحة. لو عندك أي سؤال بعد الجلسة أنا معاكِ.$b$,201,'{"states":["s11"]}')
